// Des: Plain-language recipes to steps: send, remind, price, summarize
// Flo: parse phrase (EN or VI) > pick recipe > bulk guard > run jobs through the session > report lines
// I/O: phrase text + Sess (caller) > Report counts and preview lines; AI only if enabled
// ===================================================================
const std = @import("std"); const sess = @import("ru-sess-ctxz.zig"); const rd = @import("ru-chat-read.zig"); const snd = @import("ru-chat-send.zig"); const rem = @import("ru-chat-remi.zig"); const halt = @import("ru-safe-halt.zig"); const ai = @import("ru-smar-adap.zig");
const CF = .{ .sndp = @as([]const []const u8, &.{ "send ", "gửi ", "gui " }), .rmdp = @as([]const []const u8, &.{ "remind ", "nhắc ", "nhac " }), .atwd = @as([]const []const u8, &.{ " at ", " lúc ", " luc " }), .towd = @as([]const []const u8, &.{ " to ", ": ", " để ", " de " }), .pric = "answer price questions", .summ = "summarize unread", .titl = "Reminder", .hist = 6 };
pub const Recipe = union(enum) { send: struct { chat: []const u8, text: []const u8 }, remind: struct { chat: []const u8, whenz: []const u8, titl: []const u8 }, price, summ };
pub const Report = struct { sent: u32 = 0, prev: u32 = 0, skip: u32 = 0, lines: []const []const u8 = &.{} };
fn strip(txt: []const u8, pref: []const []const u8) ?[]const u8 { for (pref) |pre| { if (txt.len >= pre.len and std.ascii.eqlIgnoreCase(txt[0..pre.len], pre)) return std.mem.trim(u8, txt[pre.len..], " "); } return null; }
fn cut(txt: []const u8, seps: []const []const u8) ?struct { head: []const u8, tail: []const u8 } { var best: ?usize = null; var blen: usize = 0; for (seps) |sep| { if (std.ascii.findIgnoreCase(txt, sep)) |idx| { if (best == null or idx < best.?) { best = idx; blen = sep.len; } } } const idx = best orelse return null; return .{ .head = std.mem.trim(u8, txt[0..idx], " "), .tail = std.mem.trim(u8, txt[idx + blen ..], " ") }; }
pub fn parse(text: []const u8) !Recipe { const trm = std.mem.trim(u8, text, " \r\n\t"); if (std.ascii.eqlIgnoreCase(trm, CF.pric)) return .price; if (std.ascii.eqlIgnoreCase(trm, CF.summ)) return .summ; if (strip(trm, CF.sndp)) |rest| { const sp = cut(rest, &.{":"}) orelse return error.BadJob; if (sp.head.len == 0 or sp.tail.len == 0) return error.BadJob; return .{ .send = .{ .chat = sp.head, .text = sp.tail } }; } if (strip(trm, CF.rmdp)) |rest| { const sp = cut(rest, CF.atwd) orelse return error.BadJob; if (sp.head.len == 0) return error.BadJob; if (cut(sp.tail, CF.towd)) |tt| { if (tt.head.len == 0) return error.BadJob; return .{ .remind = .{ .chat = sp.head, .whenz = tt.head, .titl = if (tt.tail.len == 0) CF.titl else tt.tail } }; } if (sp.tail.len == 0) return error.BadJob; return .{ .remind = .{ .chat = sp.head, .whenz = sp.tail, .titl = CF.titl } }; } return error.BadJob; }
fn hasWord(aren: std.mem.Allocator, text: []const u8, words: []const []const u8) !bool { const low = try halt.lowFold(aren, text); for (words) |wrd| { if (wrd.len == 0) continue; if (std.mem.find(u8, low, try halt.lowFold(aren, wrd)) != null) return true; } return false; }
fn tally(rep: *Report, out: snd.Out) void { switch (out) { .sent => rep.sent += 1, .dry => rep.prev += 1, .dup => rep.skip += 1 } }
pub fn fill(aren: std.mem.Allocator, text: []const u8, name: []const u8) ![]const u8 { var out: std.ArrayList(u8) = .empty; var idx: usize = 0; while (idx < text.len) { if (std.mem.startsWith(u8, text[idx..], "{name}")) { try out.appendSlice(aren, name); idx += 6; } else { try out.append(aren, text[idx]); idx += 1; } } return out.items; }
fn priceRun(ses: *sess.Sess) !Report { var rep: Report = .{}; var lines: std.ArrayList([]const u8) = .empty; const chats = try rd.listChats(ses); var names: std.ArrayList([]const u8) = .empty; for (chats) |cht| { if (cht.unre) try names.append(ses.aren, cht.name); } var plan: std.ArrayList([2][]const u8) = .empty; for (names.items) |nam| { _ = rd.readChat(ses, nam) catch |err| { if (err == error.NoElem) continue; return err; }; const tail = try ses.sto.msgTail(ses.aren, nam, CF.hist); if (tail.len == 0 or !std.mem.eql(u8, tail[tail.len - 1].who, "them")) continue; if (!try hasWord(ses.aren, tail[tail.len - 1].body, ses.cfg.reci_pric_word)) continue; var repl: []const u8 = ses.cfg.reci_pric_text; if (ses.cfg.smar_mode_enab) { const used = try ses.sto.kindSince("ai", ses.now() - 86400000); if (used < ses.cfg.smar_calls_dayz) { try ses.sto.actAdd(ses.now(), "ai"); repl = ai.draft(ses.aren, ses.iozz, ses.cfg, tail) catch ses.cfg.reci_pric_text; } else ses.logz("info", "AI daily cap reached, template used"); } repl = try fill(ses.aren, repl, nam); if (repl.len == 0) { rep.skip += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "skip {s}: no reply text (set reci_pric_text or enable AI)", .{nam})); continue; } try plan.append(ses.aren, .{ nam, repl }); }
if (ses.mode == .live and plan.items.len > ses.cfg.reci_bulk_maxz) return error.NeedForce; for (plan.items) |item| { const out = try snd.sendText(ses, item[0], item[1]); tally(&rep, out); try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "{s}: {s}", .{ item[0], item[1] })); } rep.lines = lines.items; return rep; }
fn summRun(ses: *sess.Sess) !Report { var rep: Report = .{}; var lines: std.ArrayList([]const u8) = .empty; const chats = try rd.listChats(ses); var names: std.ArrayList([]const u8) = .empty; for (chats) |cht| { if (cht.unre) try names.append(ses.aren, cht.name); } for (names.items) |nam| { _ = rd.readChat(ses, nam) catch |err| { if (err == error.NoElem) continue; return err; }; const tail = try ses.sto.msgTail(ses.aren, nam, 1); if (tail.len == 0) continue; rep.prev += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "{s}: {s}", .{ nam, tail[0].body })); } rep.lines = lines.items; return rep; }
pub fn run(ses: *sess.Sess, rec: Recipe) !Report { switch (rec) { .send => |sen| { var rep: Report = .{}; const outc = try snd.sendText(ses, sen.chat, sen.text); tally(&rep, outc); const ln = try std.fmt.allocPrint(ses.aren, "{s} {s}: {s}", .{ @tagName(outc), sen.chat, sen.text }); const arr = try ses.aren.alloc([]const u8, 1); arr[0] = ln; rep.lines = arr; return rep; }, .remind => |rmd| { var rep: Report = .{}; if (try rem.remind(ses, rmd.chat, rmd.titl, rmd.whenz)) { rep.sent += 1; } else rep.prev += 1; return rep; }, .price => return priceRun(ses), .summ => return summRun(ses) } }
